import{c as e,Q as r,j as t,m as i}from"./chunks/framework.BPKcPtvA.js";const h=JSON.parse('{"title":"Your profile","description":"Set a display name and avatar on your GateKeeper account.","frontmatter":{"title":"Your profile","description":"Set a display name and avatar on your GateKeeper account."},"headers":[],"relativePath":"auth/profile.md","filePath":"auth/profile.md"}'),o={name:"auth/profile.md"};function n(s,a,p,l,d,c){return r(),t("div",null,[...a[0]||(a[0]=[i('<p>Your profile page at <code>/</code> (the home screen after sign-in) lets you set a display name and pull in a Gravatar avatar.</p><h2 id="display-name" tabindex="-1">Display name <a class="header-anchor" href="#display-name" aria-label="Permalink to &quot;Display name&quot;">​</a></h2><p>Enter a name in the <strong>Display name</strong> field and click <strong>Save</strong>. This name appears in the admin audit log, the user list, and anywhere your account is shown in the interface.</p><p>If no display name is set, your email address is shown instead.</p><h2 id="avatar" tabindex="-1">Avatar <a class="header-anchor" href="#avatar" aria-label="Permalink to &quot;Avatar&quot;">​</a></h2><p>GateKeeper uses <a href="https://gravatar.com" target="_blank" rel="noreferrer">Gravatar</a> for profile pictures. Gravatar links your picture to your email address. If you have a Gravatar account with the same email you use to sign in, click the refresh icon next to your avatar circle to pull it in.</p><p>The image is fetched server-side and cached in the database - your email address is never exposed to Gravatar from the browser.</p><p>If no Gravatar exists for your email, your initials are shown instead.</p><p>To update your avatar after changing your Gravatar picture, click the refresh icon again.</p>',9)])])}const m=e(o,[["render",n]]);export{h as __pageData,m as default};
